/// Forms spytial-core has deprecated, in the order the manifest lists them.
pub static DEPRECATIONS: &[DeprecationSpec] = &[
    DeprecationSpec { attr: "icon", when_any_key: &[], replaced_by: "atom_style", note: "The single `showLabels` boolean drove label visibility and icon geometry at once. atomStyle splits those into two independent knobs, which is what makes a faded watermark, or a hidden label with no icon, expressible. Mapping: path -> icon_style.path; show_labels: false -> show_label: false + icon_style.placement: full; show_labels: true -> show_label: true + icon_style.placement: badge." },
    DeprecationSpec { attr: "atom_color", when_any_key: &[], replaced_by: "atom_style", note: "atomStyle expresses the same recolor and also reaches the fill, the icon, and the label. The rewrite is border-preserving, so an existing diagram is unchanged. Mapping: value -> border_style.color." },
    DeprecationSpec { attr: "edge_style", when_any_key: &["value", "style", "weight"], replaced_by: "edge_style", note: "edgeStyle groups the same knobs into the shared lineStyle/textStyle blocks that every other form uses. Mapping: value -> line_style.color; style -> line_style.pattern; weight -> line_style.weight; highlight -> line_style.highlight." },
];

/// Forms that accept a `source: { text, location }` block (spytial-core 5.4),
/// by YAML key. The derive stamps every one of them; `flag` is a bare scalar
/// and has nowhere to carry one.
pub static SOURCE_SUPPORTED_BY: &[&str] = &[
    "orientation",
    "cyclic",
    "align",
    "group",
    "size",
    "hideAtom",
    "atomStyle",
    "edgeStyle",
    "attribute",
    "tag",
    "hideField",
    "inferredEdge",
    "icon",
    "atomColor",
    "edgeColor",
];

/// The forms whose `source` the viewer shows in conflict reports and
/// warnings. On the rest it is parsed and ignored.
pub static SOURCE_DISPLAYED_BY: &[&str] = &["orientation", "cyclic", "align", "group", "hideAtom"];

/// Direction pairs `orientation` rejects together (`above` with `below`,
/// `left` with `right`). spytial-core enforces these at parse time.
pub static ORIENTATION_AT_MOST_ONE_OF: &[&[&str]] = &[&["above", "below"], &["left", "right"]];

/// A `directly*` direction narrows the rest of the list to these values.
pub static ORIENTATION_NARROWS_TO: &[(&str, &[&str])] = &[
    ("directlyAbove", &["above", "directlyAbove"] as &[&str]),
    ("directlyBelow", &["below", "directlyBelow"] as &[&str]),
    ("directlyLeft", &["left", "directlyLeft"] as &[&str]),
    ("directlyRight", &["right", "directlyRight"] as &[&str]),
];
